const wc_class_info *wc_class_by_id(uint8_t id)
{
    for (size_t i = 0; i < sizeof class_info / sizeof class_info[0]; i++) {
        if (class_info[i].id == id) {
            return &class_info[i];
        }
    }
    return NULL;
}

size_t wc_class_count(void)
{
    return sizeof class_info / sizeof class_info[0];
}
